ops.replace:
   // the creatures
   // _eetmr_graph_accumulator_v1: clear SFO_visited_nodes ONCE before the loop and then
   // call iter_resource with keep_visited=1 so the 11 spells share their traversal state.
   // Each summoning spell's graph overlaps heavily with the previous ones (common creatures
   // across MS1-7, Carrion, Wyvern Call, Spider Spawn); without this, every call re-walks
   // the shared subgraph from scratch, generating 237k COPY_EXISTING/DECOMPILE operations
   // (~3h wall clock on a full EET install).
   ACTION_CLEAR_ARRAY SFO_visited_nodes
   ACTION_CLEAR_ARRAY array_cre 
   OUTER_WHILE "%spell_list%" STR_CMP "" BEGIN
		LAF return_first_entry STR_VAR list="%spell_list%" RET spell_list=list spell=entry END
		ACTION_IF FILE_EXISTS_IN_GAME "%spell%.spl" BEGIN
			LAF iter_resource INT_VAR keep_visited=1 STR_VAR start="%spell%.spl" RET_ARRAY array_here=array END

// _eetmr_dedupe_ms1_v1: removed one duplicate %WIZARD_MONSTER_SUMMONING_1% from the
// spell_list below â€” saves one full iter_resource graph walk (~15-20 min on EET megainstalls).
DEFINE_PATCH_FUNCTION EMPOWERED_MONSTER_SUMMONING BEGIN

	LPF empowered_creature_setup STR_VAR script="%baf_empowered_monster_summons%" splstate=DW_POWER_UPGRADE_C5 spell_list="%WIZARD_MONSTER_SUMMONING_1% %WIZARD_MONSTER_SUMMONING_2%

