ops.replace:
// _eetmr_bcs_prefilter_v2: Class trigger ID
LAF disjunctive_substitution STR_VAR script match="Class(\([^,]*\),DRUID_ALL)" replace="OR()Class(\1,DRUID_ALL)|CheckSpellState(\1,DW_DRUID)" pre_filter="16396" END
LAF disjunctive_substitution STR_VAR script match="Class(\([^,]*\),CLERIC_ALL)" replace="Class(\1,CLERIC_ALL)|!CheckSpellState(\1,DW_DRUID)" pre_filter="16396" END

// _eetmr_ds_patch_try: wrap LPF calls in PATCH_TRY so corrupted items
// (broken ability offsets) emit a warning instead of aborting the component.
// Triggered by POTN18 (Test #38) + POTN45 (Test #39) having inconsistent
// ability-header offsets after upstream mods patched them â€” WeiDU's
// CLONE_EFFECT walker then crashes with "cannot convert abil_num to an
// integer". PATCH_TRY catches this and lets the rest of the DS registration
// proceed.
COPY_EXISTING "%filespec%" override
  PATCH_TRY
      LPF DELETE_EFFECT INT_VAR match_opcode=stat_opcode match_parameter2=stat_param END // clear out any previous version
      LPF CLONE_EFFECT INT_VAR silent=!complain multi_match=1 match_opcode match_parameter2 opcode=stat_opcode parameter1=stat_value parameter2=stat_param special=(opcode=328) STR_VAR match_resource END
  WITH
    DEFAULT
      PATCH_PRINT "_eetmr_ds_patch_try: skipped corrupted item %filespec% (ability walker crashed); DS tracking for this resource is unavailable"
  END
BUT_ONLY
